:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-tile: #f9f8f6;
  --color-fog-wash: #0a0a0a0a;
  --color-mist-wash: #0a0a0a14;
  --color-onyx-terminal: #151515;
  --color-ink: #0a0a0a;
  --color-stone-ink: #59534d;
  --color-graphite-caption: #0a0a0a99;
  --color-steel-tab: #7d8187;
  --color-pebble-caption: #8d867e;
  --color-ash-hairline: #0a0a0a0f;
  --color-ember-signal: #ff6308;
  --color-ember-tint: #ff63081a;

  /* Typography — Font Families */
  --font-xvf: "xVf", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "GeistMono", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-system-ui: system-ui, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.5;
  --tracking-small: 0.5px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.625;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.43;
  --tracking-body: 0px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.625;
  --tracking-body-lg: 0px;
  --text-subheading: 18px;
  --leading-subheading: 1.625;
  --tracking-subheading: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.333;
  --tracking-heading-sm: -0.24px;
  --text-heading: 30px;
  --leading-heading: 1.2;
  --tracking-heading: -0.3px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -0.48px;
  --text-display: 60px;
  --leading-display: 1;
  --tracking-display: -0.6px;

  /* Typography — Weights */
  --font-weight-light: 450; /* the display "book" weight, lighter than medium */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1280px;
  --layout-hero-width: 768px;
  --layout-copy-width: 448px;
  --layout-section-gap: 96px;
  --layout-card-padding: 40px;
  --layout-element-gap: 12px;
  --layout-nav-height: 64px;

  /* Border Radius */
  --radius-sm: 3px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-cards: 16px;
  --radius-inner-tiles: 12px;
  --radius-small-cards: 8px;
  --radius-images: 8px;
  --radius-small-elements: 6px;
  --radius-tags: 3px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(255, 255, 255, 0.03) 0px 1px 0px 0px inset;
  --shadow-subtle-2: rgba(255, 255, 255, 0.7) 0px 1px 1px 0px inset, rgba(255, 255, 255, 0.45) 0px -1px 1px 0px inset, rgba(255, 255, 255, 0.22) 0px 0px 0px 1px inset, rgba(255, 255, 255, 0.18) 0px 0px 13.1px 0px inset;
  --shadow-sm: rgba(10, 10, 10, 0.15) 0px 0px 0px 1px inset;
  --shadow-md: rgba(0, 0, 0, 0.06) 0px 0px 0px 1px, rgba(15, 23, 42, 0.18) 0px 18px 40px -24px;
  --shadow-lg: rgba(0, 0, 0, 0.22) 0px 16px 48px -8px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-tile: #f9f8f6;
  --surface-fog-wash: #0a0a0a0a;
  --surface-onyx-terminal: #151515;
}

